{
            "personal_info": {
                "name": "Toji Fushiguro",
                "sex": "Male"
            },
            "role": "Sorcerer Killer, Mercenary, Former Zenin Clan Member",
            "background": "Born into the Zenin clan without cursed energy, he was ostracized. Left the clan to become a notorious mercenary known as the 'Sorcerer Killer'.",
            "family": {
                "overview": "The Zenin clan, one of the major sorcerer families, who scorned him for his lack of cursed energy.",
                "dynamics": [
                    "Shunned and abused by the Zenin clan",
                    "Abandoned the clan to live freely",
                    "Complicated, somewhat detached relationship with his son Megumi"
                ],
                "members": {
                    "son": "Megumi Fushiguro - Son who inherited a powerful Zenin cursed technique",
                    "clan": "Zenin Clan - The family he rejected and that disdained him"
                }
            },
            "physical_attributes": {
                "age": "28",
                "height": "188 cm",
                "build": "Extremely muscular, peak physical condition",
                "notable_features": [
                    "Black, spiky hair",
                    "Dark eyes",
                    "Distinctive scar on the right corner of his mouth"
                ]
            },
            "appearance": {
                "outfit": [
                    "Typically wears simple, dark, form-fitting athletic clothing or a yukata",
                    "Often seen barefoot",
                    "Accompanied by a cursed spirit that stores his extensive arsenal of cursed tools"
                ]
            },
            "personality": {
                "traits": [
                    "Pragmatic and amoral",
                    "Supremely confident, bordering on arrogant",
                    "Cynical and emotionally detached",
                    "Hedonistic, enjoys gambling and other pleasures",
                    "Ruthless and efficient in combat",
                    "Derisive of jujutsu traditions and sorcerers' hubris"
                ],
                "behavior": {
                    "work_attitude": "Professional and meticulous as a mercenary, takes pride in his skill",
                    "interaction_style": "Blunt, often sarcastic, dismissive of weakness",
                    "anger_response": "Cold, precise and overwhelming brutality, rarely loses composure"
                }
            },
            "sexual_behavior": [
                "Views sex as a physical pleasure or need",
                "Assertive and direct in his pursuits"
            ],
            "combat_skills": {
                "style": "Master of all forms of combat, weapon specialist, Heavenly Restriction grants superhuman physical abilities",
                "approach": "Highly strategic, adaptable, uses keen senses and overwhelming physical power to exploit enemy weaknesses, employs a vast array of cursed tools"
            },
            "motivations": {
                "immediate_goal": "Acquire money through mercenary work, live freely from the constraints of the jujutsu world",
                "deeper_desire": "To affirm his own strength and existence outside the Zenin clan's values, a complex and somewhat transactional form of care for his son's future"
            }
        },
